export function nextGeneration(cells: Cell[]): Cell[] {
  const alive = new Set(cells.map(cellKey));

  const countAliveNeighbors = ([x, y]: Cell): number =>
    NEIGHBOR_OFFSETS.filter(([dx, dy]) => alive.has(cellKey([x + dx, y + dy]))).length;

  const survivors = cells.filter((cell) => survivesWithNeighborCount(countAliveNeighbors(cell)));

  const deadNeighbors = new Map<string, Cell>();
  for (const [x, y] of cells) {
    for (const [dx, dy] of NEIGHBOR_OFFSETS) {
      const neighbor: Cell = [x + dx, y + dy];
      const k = cellKey(neighbor);
      if (!alive.has(k)) deadNeighbors.set(k, neighbor);
    }
  }
  const births: Cell[] = [];
  for (const neighbor of deadNeighbors.values()) {
    if (isBornWithNeighborCount(countAliveNeighbors(neighbor))) births.push(neighbor);
  }

  return [...survivors, ...births];
}

